//! The source Unite catalogue, parsed and validated once.
//!
//! The packet is generated by the extraction pipeline from MAIN.EXE
//! record data and instruction facts.  This module turns it into typed records
//! and refuses a packet that is not the complete 32-entry catalogue: a caller
//! can never supply a record count, a member list or a "proven" opinion.
//!
//! Source constants that stay visible here (they are the reason the schema is
//! versioned):
//!   * `B+0x48` holds a **one-based** record ordinal (matcher `0x800F91C0`
//!     computes `4*B+0x48 + 0x8016D18C`);
//!   * `+0x19` is the unite id into the action table `0x8016D2D0`;
//!   * bit 1 of the flag word `+0x16` selects the individual target picker;
//!   * a record's member list is 2..4 character ids at `+0x1A`.

const std = @import("std");

pub const schema = "suikoden-unite-catalogue/6";
pub const max_members = 4;
pub const max_records = 32;
pub const max_party = 6;

pub const TargetRule = enum { individual, bypass };
pub const EffectGate = enum { leader_hit_flag, target_active };
pub const HitActor = struct {
    kind: enum { command_owner, member },
    member: ?u8 = null,
};
pub const Family = enum { combined_physical, custom };
pub const Blocker = enum { effect_family_unestablished, handler_member_count_mismatch };
pub const Outcome = union(enum) { proven, blocked: Blocker };

pub const MemberTiming = struct { setup_ready: u16, impact: u16, ready: u16, retreat: u16 };
pub const Sequence = struct { members: []const MemberTiming, finish_delay: u16 };

pub const Record = struct {
    index: u8,
    name: []const u8,
    name_fully_decoded: bool,
    members: [max_members]u8,
    member_count: u8,
    flags: u16,
    target_rule: TargetRule,
    all_enemies: bool = false,
    sequence: ?Sequence = null,
    target_reaction_updates: ?u16 = null,
    recovery: [max_members]bool = @splat(false),
    unite_id: u8,
    handler: u32,
    update: u32,
    family: Family,
    gate: ?EffectGate,
    hit_actor: ?HitActor,
    damage_count: u8,
    multiplier: u8,
    outcome: Outcome,

    pub fn proven(self: Record) bool {
        return switch (self.outcome) {
            .proven => true,
            .blocked => false,
        };
    }

    pub fn membersSlice(self: *const Record) []const u8 {
        return self.members[0..self.member_count];
    }

    /// The byte the command commit writes to `B+0x48`.
    pub fn ordinal(self: Record) u8 {
        return self.index + 1;
    }

    pub fn hasMember(self: Record, character_id: u8) bool {
        for (self.membersSlice()) |id| if (id == character_id) return true;
        return false;
    }
};

const RawBlocker = struct {
    reason: []const u8,
    detail: []const u8,
};

const RawRecord = struct {
    index: u8,
    name: []const u8,
    name_fully_decoded: bool = true,
    members: []const u8,
    member_count: u8,
    flags: u16,
    target_rule: []const u8,
    all_enemies: bool = false,
    sequence: ?Sequence = null,
    target_reaction_updates: ?u16 = null,
    recovery: []const bool,
    unite_id: u8,
    handler: u32,
    update: u32,
    family: []const u8,
    gate: ?[]const u8 = null,
    hit_actor: ?HitActor = null,
    damage_count: u8 = 0,
    multiplier: u8 = 0,
    outcome: []const u8,
    blocker: ?RawBlocker = null,
};

const RawSummary = struct {
    records: u8,
    proven: u8,
    blocked: u8,
    distinct_unite_ids: u8 = 0,
    distinct_handlers: u8 = 0,
};

const RawPacket = struct {
    schema: []const u8,
    version: []const u8,
    records: []const RawRecord,
    summary: RawSummary,
};

pub const Catalogue = struct {
    parsed: std.json.Parsed(RawPacket),
    records: []Record,

    pub fn init(allocator: std.mem.Allocator, json: []const u8) !Catalogue {
        const parsed = try std.json.parseFromSlice(RawPacket, allocator, json, .{
            .allocate = .alloc_always,
            .ignore_unknown_fields = true,
        });
        errdefer parsed.deinit();
        if (!std.mem.eql(u8, parsed.value.schema, schema)) return error.InvalidCatalogueSchema;
        if (parsed.value.records.len != max_records) return error.InvalidCatalogueCount;
        if (parsed.value.summary.records != max_records) return error.InvalidCatalogueCount;

        const records = try allocator.alloc(Record, parsed.value.records.len);
        errdefer allocator.free(records);
        var proven: u8 = 0;
        var blocked: u8 = 0;
        for (parsed.value.records, 0..) |raw, i| {
            if (raw.index != i) return error.InvalidCatalogueIndex;
            if (raw.member_count < 2 or raw.member_count > max_members) return error.InvalidCatalogueMembers;
            if (raw.recovery.len != raw.member_count) return error.InvalidCatalogueEffect;
            if (raw.members.len != raw.member_count) return error.InvalidCatalogueMembers;
            if (raw.flags & 1 == 0) return error.InvalidCatalogueFlags;
            for (raw.members, 0..) |member, m| {
                for (raw.members[0..m]) |previous| if (previous == member) return error.InvalidCatalogueMembers;
            }
            if (raw.unite_id == 0 or raw.unite_id > 25) return error.InvalidCatalogueUniteId;
            const target_rule: TargetRule = if (std.mem.eql(u8, raw.target_rule, "individual"))
                .individual
            else if (std.mem.eql(u8, raw.target_rule, "bypass"))
                .bypass
            else
                return error.InvalidCatalogueTarget;
            if ((raw.flags & 2 != 0) != (target_rule == .individual) or (raw.all_enemies and target_rule != .bypass)) return error.InvalidCatalogueTarget;

            var record = Record{
                .index = raw.index,
                .name = raw.name,
                .name_fully_decoded = raw.name_fully_decoded,
                .members = undefined,
                .member_count = raw.member_count,
                .flags = raw.flags,
                .target_rule = target_rule,
                .all_enemies = raw.all_enemies,
                .sequence = raw.sequence,
                .target_reaction_updates = raw.target_reaction_updates,
                .unite_id = raw.unite_id,
                .handler = raw.handler,
                .update = raw.update,
                .family = undefined,
                .gate = null,
                .hit_actor = raw.hit_actor,
                .damage_count = raw.damage_count,
                .multiplier = raw.multiplier,
                .outcome = undefined,
            };
            @memset(record.members[0..], 0);
            @memcpy(record.members[0..raw.member_count], raw.members);

            if (raw.sequence) |sequence| {
                if (raw.index != 31 or sequence.members.len != raw.member_count or raw.all_enemies or target_rule != .bypass or sequence.finish_delay > 1000) return error.InvalidCatalogueEffect;
                for (sequence.members) |timing| if (timing.setup_ready == 0 or timing.impact == 0 or timing.ready <= timing.impact or timing.retreat == 0 or timing.setup_ready > 1000 or timing.ready > 1000 or timing.retreat > 1000) return error.InvalidCatalogueEffect;
            }
            if (raw.target_reaction_updates) |updates| if (updates == 0 or updates > 1000) return error.InvalidCatalogueEffect;
            @memcpy(record.recovery[0..raw.member_count], raw.recovery);
            if (std.mem.eql(u8, raw.outcome, "proven")) {
                if (!std.mem.eql(u8, raw.family, "combined_physical")) return error.InvalidCatalogueEffect;
                if (raw.damage_count != raw.member_count) return error.InvalidCatalogueEffect;
                if (raw.multiplier == 0) return error.InvalidCatalogueEffect;
                record.family = .combined_physical;
                record.gate = if (raw.gate) |gate|
                    if (std.mem.eql(u8, gate, "leader_hit_flag"))
                        EffectGate.leader_hit_flag
                    else if (std.mem.eql(u8, gate, "target_active"))
                        EffectGate.target_active
                    else
                        return error.InvalidCatalogueEffect
                else
                    return error.InvalidCatalogueEffect;
                if (record.gate == .leader_hit_flag) {
                    const actor = raw.hit_actor orelse return error.InvalidCatalogueEffect;
                    switch (actor.kind) {
                        .command_owner => if (actor.member != null) return error.InvalidCatalogueEffect,
                        .member => if ((actor.member orelse return error.InvalidCatalogueEffect) >= raw.member_count) return error.InvalidCatalogueEffect,
                    }
                } else if (raw.hit_actor != null) return error.InvalidCatalogueEffect;
                record.outcome = .proven;
                proven += 1;
            } else if (std.mem.eql(u8, raw.outcome, "blocked")) {
                const blocker = raw.blocker orelse return error.InvalidCatalogueEffect;
                const reason: Blocker = if (std.mem.eql(u8, blocker.reason, "effect_family_unestablished"))
                    .effect_family_unestablished
                else if (std.mem.eql(u8, blocker.reason, "handler_member_count_mismatch"))
                    .handler_member_count_mismatch
                else
                    return error.InvalidCatalogueEffect;
                if (!std.mem.eql(u8, raw.family, "custom") and reason == .effect_family_unestablished)
                    return error.InvalidCatalogueEffect;
                record.family = if (std.mem.eql(u8, raw.family, "custom")) .custom else .combined_physical;
                record.outcome = .{ .blocked = reason };
                blocked += 1;
            } else {
                return error.InvalidCatalogueEffect;
            }
            records[i] = record;
        }
        if (proven != parsed.value.summary.proven or blocked != parsed.value.summary.blocked)
            return error.InvalidCatalogueSummary;

        // A record is identified by its member set; two records may share a
        // name (the Blacksmith permutations) but never the same member set.
        for (records, 0..) |a, i| {
            for (records[0..i]) |b| {
                if (a.member_count != b.member_count) continue;
                var same = true;
                for (a.membersSlice()) |member| {
                    if (!b.hasMember(member)) same = false;
                }
                if (same) return error.InvalidCatalogueMembers;
            }
        }

        return .{ .parsed = parsed, .records = records };
    }

    pub fn deinit(self: *Catalogue, allocator: std.mem.Allocator) void {
        allocator.free(self.records);
        self.parsed.deinit();
    }

    pub fn count(self: Catalogue) usize {
        return self.records.len;
    }

    pub fn recordAt(self: Catalogue, index: u8) ?*const Record {
        if (@as(usize, index) >= self.records.len) return null;
        return &self.records[index];
    }

    /// Resolve the source `B+0x48` ordinal (one-based) to a record.
    pub fn recordByOrdinal(self: Catalogue, ordinal: u8) ?*const Record {
        if (ordinal == 0) return null;
        return self.recordAt(ordinal - 1);
    }

    /// Records whose member list contains `character_id`.
    pub fn containing(self: Catalogue, character_id: u8, out: []usize) usize {
        var n: usize = 0;
        for (self.records, 0..) |record, i| {
            if (!record.proven()) continue;
            if (record.hasMember(character_id)) {
                if (n == out.len) break;
                out[n] = i;
                n += 1;
            }
        }
        return n;
    }

    pub fn provenCount(self: Catalogue) usize {
        var n: usize = 0;
        for (self.records) |record| if (record.proven()) {
            n += 1;
        };
        return n;
    }

    pub fn blockedCount(self: Catalogue) usize {
        return self.records.len - self.provenCount();
    }
};
